from pathlib import Path
import struct,hashlib,json
p=Path(r'D:\tmp2b\fm24\input\editor.exe'); d=p.read_bytes()
print('sha256 editor.exe',hashlib.sha256(d).hexdigest())
for value,name in [(0x140ebfa40,'VA fn@ebf040'),(0xebfa40,'RVA fn'),(0xebf040,'fileoff fn')]:
 b=struct.pack('<Q' if value>0xffffffff else '<I',value); hits=[]; st=0
 while (i:=d.find(b,st))>=0: hits.append(i); st=i+1
 print(name,hex(value),b.hex(),[hex(x) for x in hits[:100]],'count',len(hits))
# direct call-to-helperB followed immediately by stride instruction
out=[]
for i in range(0x600,0x1758600-9):
 if d[i]==0xe8:
  rel=struct.unpack_from('<i',d,i+1)[0]
  if i+5+rel==0x83caf0 and d[i+5:i+9]==bytes.fromhex('48 83 c0 38'):
   out.append(i)
print('call helperB; add rax,38 count',len(out),'first 120',[hex(x) for x in out[:120]])
# 4cc imm-compare hits around late second cluster
for code in ('ccti','cnti','cpcm','rdui','duni'):
 needle=code.encode()[::-1]
 hits=[]; st=0
 while (i:=d.find(needle,st))>=0:
  if 0xec0000<=i<0xed0000: hits.append(i)
  st=i+1
 print(code,'late cluster', [hex(x) for x in hits])
# snapshot manifest entry for provenance
m=json.loads(Path('evidence/MANIFEST.json').read_text(encoding='utf-8'))
for f in m['files']:
 if f['path'].endswith('IDA_PROVENANCE.md'): print('manifest provenance',f)
