from pathlib import Path
import struct,json
D=Path(r'D:\tmp2b\fm24\input\editor.exe').read_bytes()
m=json.loads(Path('evidence/fm24/reports/editor_schema/master.json').read_text(encoding='utf-8'))
entities=m.get('entity_summary',{})
by_codes={e:set(v.get('codes',[])) for e,v in entities.items()}
hits=[]
for i in range(0x600,0x1758600-5):
 if D[i]==0xe8 and i+5+struct.unpack_from('<i',D,i+1)[0]==0x83abf0:
  # nearest exact register-code immediate before call
  j=D.rfind(bytes.fromhex('c7 45 f0'),max(0,i-36),i)
  code=None
  if j>=0 and j+7<=i:
   imm=struct.unpack_from('<I',D,j+3)[0]
   code=struct.pack('>I',imm).decode('ascii','replace')
  hits.append((i,code))
# sequences at 0x30 spacing, only code available
runs=[]; cur=[]
for h in hits:
 if cur and h[0]-cur[-1][0]==0x30: cur.append(h)
 else:
  if len(cur)>=4:runs.append(cur)
  cur=[h]
if len(cur)>=4:runs.append(cur)
print('runs >=4 every 0x30:',len(runs))
for run in runs:
 codes=[c for _,c in run]
 matches=[]
 for ent,ec in by_codes.items():
  overlap=len(set(codes)&ec)
  if overlap>=3: matches.append((overlap,ent))
